@pytest.mark.parametrize("source_ip", VALID_IPS)
def test_valid_ipv4_is_preserved(source_ip):
    event = SecurityEventIn(
        timestamp="2026-01-01T00:00:00Z",
        event_type="login_failure",
        username="lab-user",
        source_ip=source_ip,
        host="lab-host",
    )
    assert event.source_ip == source_ip
